def localize_type(kind: str, lang: str) -> str:
    return {'Modificado':'Modified','Añadido':'Added','Eliminado':'Removed'}.get(kind,kind) if lang=='en' else kind

def localize_severity(sev: str, lang: str) -> str:
    return {'Alta':'High','Media':'Medium','Baja':'Low'}.get(sev,sev) if lang=='en' else sev
